39	
40	import org.slf4j.Logger;
41	import org.slf4j.LoggerFactory;
42	
43	import org.apache.hadoop.classification.InterfaceAudience;
44	import org.apache.hadoop.classification.InterfaceStability;
45	import org.apache.hadoop.fs.FSDataInputStream;
46	import org.apache.hadoop.fs.FileSystem;
47	import org.apache.hadoop.fs.Path;
48	
49	/**
50	 * Support for marshalling objects to and from JSON.
51	 *
52	 * It constructs an object mapper as an instance field.
53	 * and synchronizes access to those methods
54	 * which use the mapper.
55	 *
56	 * This class was extracted from
57	 * {@code org.apache.hadoop.registry.client.binding.JsonSerDeser},
58	 * which is now a subclass of this class.
59	 * @param <T> Type to marshal.
60	 */
61	@InterfaceAudience.Private
62	@InterfaceStability.Evolving
63	public class JsonSerialization<T> {
64	
65	  private static final Logger LOG =
66	      LoggerFactory.getLogger(JsonSerialization.class);
67	  private static final String UTF_8 = "UTF-8";
68	
69	  private final Class<T> classType;
70	  private final ObjectMapper mapper;
71	
72	  private static final ObjectWriter WRITER =
73	      new ObjectMapper().writerWithDefaultPrettyPrinter();
74	
75	  private static final ObjectReader MAP_READER =
76	      new ObjectMapper().readerFor(Map.class);
77	
78	  /**
79	   * @return an ObjectWriter which pretty-prints its output
80	   */
81	  public static ObjectWriter writer() {
82	    return WRITER;
83	  }
84	
85	  /**
86	   * @return an ObjectReader which returns simple Maps.
87	   */
88	  public static ObjectReader mapReader() {
89	    return MAP_READER;
90	  }
91	
92	  /**
93	   * Create an instance bound to a specific type.
94	   * @param classType class to marshall
95	   * @param failOnUnknownProperties fail if an unknown property is encountered.
96	   * @param pretty generate pretty (indented) output?
97	   */
98	  public JsonSerialization(Class<T> classType,
99	      boolean failOnUnknownProperties, boolean pretty) {
100	    Preconditions.checkArgument(classType != null, "null classType");
101	    this.classType = classType;
102	    this.mapper = new ObjectMapper();
103	    mapper.configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES,
104	        failOnUnknownProperties);
105	    mapper.configure(SerializationFeature.INDENT_OUTPUT, pretty);
106	  }
107	
108	  /**
109	   * Get the simple name of the class type to be marshalled.
110	   * @return the name of the class being marshalled
111	   */
112	  public String getName() {
113	    return classType.getSimpleName();
114	  }
115	
116	  /**
117	   * Get the mapper of this class.
118	   * @return the mapper
119	   */
120	  public ObjectMapper getMapper() {
121	    return mapper;
122	  }
123	
124	  /**
125	   * Convert from JSON.
126	   *
127	   * @param json input
128	   * @return the parsed JSON
129	   * @throws IOException IO problems
130	   * @throws JsonParseException If the input is not well-formatted
131	   * @throws JsonMappingException failure to map from the JSON to this class
132	   */
133	  @SuppressWarnings("unchecked")
134	  public synchronized T fromJson(String json)
135	      throws IOException, JsonParseException, JsonMappingException {
136	    if (json.isEmpty()) {
137	      throw new EOFException("No data");
138	    }
139	    try {
140	      return mapper.readValue(json, classType);
141	    } catch (IOException e) {
142	      LOG.error("Exception while parsing json : {}\n{}", e, json, e);
143	      throw e;
144	    }
145	  }
146	
147	  /**
148	   * Read from an input stream.
149	   * @param stream stream to read from
150	   * @return the parsed entity
151	   * @throws IOException IO problems
152	   * @throws JsonParseException If the input is not well-formatted
153	   * @throws JsonMappingException failure to map from the JSON to this class
154	   */
155	  public synchronized T fromJsonStream(InputStream stream) throws IOException {
156	    return mapper.readValue(stream, classType);
157	  }
158	
159	  /**
160	   * Load from a JSON text file.
161	   * @param jsonFile input file
162	   * @return the parsed JSON
163	   * @throws IOException IO problems
164	   * @throws JsonParseException If the input is not well-formatted
165	   * @throws JsonMappingException failure to map from the JSON to this class
166	   */
167	  @SuppressWarnings("unchecked")
168	  public synchronized T load(File jsonFile)
169	      throws IOException, JsonParseException, JsonMappingException {
170	    if (!jsonFile.isFile()) {
171	      throw new FileNotFoundException("Not a file: " + jsonFile);
172	    }
173	    if (jsonFile.length() == 0) {
174	      throw new EOFException("File is empty: " + jsonFile);
175	    }
176	    try {
177	      return mapper.readValue(jsonFile, classType);
178	    } catch (IOException e) {
179	      LOG.error("Exception while parsing json file {}", jsonFile, e);
180	      throw e;
181	    }
182	  }
183	
184	  /**
185	   * Save to a local file. Any existing file is overwritten unless
186	   * the OS blocks that.
187	   * @param file file
188	   * @param instance instance
189	   * @throws IOException IO exception
190	   */
191	  public void save(File file, T instance) throws
192	      IOException {
193	    writeJsonAsBytes(instance, Files.newOutputStream(file.toPath()));
194	  }
195	
196	  /**
197	   * Convert from a JSON file.
198	   * @param resource input file
199	   * @return the parsed JSON
200	   * @throws IOException IO problems
201	   * @throws JsonParseException If the input is not well-formatted
202	   * @throws JsonMappingException failure to map from the JSON to this class
203	   */
204	  @SuppressWarnings({"IOResourceOpenedButNotSafelyClosed"})
205	  public synchronized T fromResource(String resource)
206	      throws IOException, JsonParseException, JsonMappingException {
207	    try (InputStream resStream = this.getClass()
208	        .getResourceAsStream(resource)) {
209	      if (resStream == null) {
210	        throw new FileNotFoundException(resource);
211	      }
212	      return mapper.readValue(resStream, classType);
213	    } catch (IOException e) {
214	      LOG.error("Exception while parsing json resource {}", resource, e);
215	      throw e;
216	    }
217	  }
218	
219	  /**
220	   * clone by converting to JSON and back again.
221	   * This is much less efficient than any Java clone process.
222	   * @param instance instance to duplicate
223	   * @return a new instance
224	   * @throws IOException IO problems.
225	   */
226	  public T fromInstance(T instance) throws IOException {
227	    return fromJson(toJson(instance));
228	  }
229	
230	  /**
231	   * Load from a Hadoop filesystem.
232	   * There's a check for data availability after the file is open, by
233	   * raising an EOFException if stream.available == 0.
234	   * This allows for a meaningful exception without the round trip overhead
235	   * of a getFileStatus call before opening the file. It may be brittle
236	   * against an FS stream which doesn't return a value here, but the
237	   * standard filesystems all do.
238	   * JSON parsing and mapping problems
239	   * are converted to IOEs.
240	   * @param fs filesystem
241	   * @param path path
242	   * @return a loaded object
243	   * @throws IOException IO or JSON parse problems
244	   */
245	  public T load(FileSystem fs, Path path) throws IOException {
246	    try (FSDataInputStream dataInputStream = fs.open(path)) {
247	      // throw an EOF exception if there is no data available.
248	      if (dataInputStream.available() == 0) {
249	        throw new EOFException("No data in " + path);
250	      }
251	      return fromJsonStream(dataInputStream);
252	    } catch (JsonProcessingException e) {
253	      throw new IOException(
254	          String.format("Failed to read JSON file \"%s\": %s", path, e),
255	          e);
256	    }
257	  }
258	
259	  public T load(FileSystem fs, Path path,
260	      org.apache.hadoop.fs.FileStatus status) throws IOException {
261	    if (status != null && status.getLen() == 0) {
262	      throw new EOFException("No data in " + path);
263	    }
264	    return load(fs, path);
265	  }
266	
267	  /**
268	   * Save to a Hadoop filesystem.
269	   * @param fs filesystem
270	   * @param path path
271	   * @param overwrite should any existing file be overwritten
272	   * @throws IOException IO exception
273	   */
274	  public void save(FileSystem fs, Path path, T instance,
275	      boolean overwrite) throws
276	      IOException {
277	    writeJsonAsBytes(instance, fs.create(path, overwrite));
278	  }
279	
280	  /**
281	   * Write the JSON as bytes, then close the file.
282	   * @param dataOutputStream an output stream that will always be closed
283	   * @throws IOException on any failure
284	   */
285	  private void writeJsonAsBytes(T instance,
286	      OutputStream dataOutputStream) throws IOException {
287	    try {
288	      dataOutputStream.write(toBytes(instance));
289	    } finally {
290	      dataOutputStream.close();
291	    }
292	  }
293	
294	  /**
295	   * Convert JSON to bytes.
296	   * @param instance instance to convert
297	   * @return a byte array
298	   * @throws IOException IO problems
299	   */
300	  public byte[] toBytes(T instance) throws IOException {
301	    return mapper.writeValueAsBytes(instance);
302	  }
303	
304	  /**
305	   * Deserialize from a byte array.
306	   * @param bytes byte array
307	   * @throws IOException IO problems
308	   * @throws EOFException not enough data
309	   */
310	  public T fromBytes(byte[] bytes) throws IOException {
311	    return fromJson(new String(bytes, 0, bytes.length, UTF_8));
312	  }
313	
314	  /**
315	   * Convert an instance to a JSON string.
316	   * @param instance instance to convert
317	   * @return a JSON string description
318	   * @throws JsonProcessingException Json generation problems
319	   */
320	  public synchronized String toJson(T instance) throws JsonProcessingException {
321	    return mapper.writeValueAsString(instance);
322	  }
323	
324	  /**
325	   * Convert an instance to a string form for output. This is a robust
326	   * operation which will convert any JSON-generating exceptions into
327	   * error text.
328	   * @param instance non-null instance
329	   * @return a JSON string
330	   */
331	  public String toString(T instance) {
332	    Preconditions.checkArgument(instance != null, "Null instance argument");
333	    try {
334	      return toJson(instance);
335	    } catch (JsonProcessingException e) {
336	      return "Failed to convert to a string: " + e;
337	    }
338	  }
339	}
