37	/**
38	 * Test the JSON serialization helper.
39	 */
40	public class TestJsonSerialization extends HadoopTestBase {
41	
42	  private final JsonSerialization<KeyVal> serDeser =
43	      new JsonSerialization<>(KeyVal.class, true, true);
44	
45	  private final KeyVal source = new KeyVal("key", "1");
46	
47	  private static class KeyVal implements Serializable {
48	    private String name;
49	    private String value;
50	
51	    KeyVal(String name, String value) {
52	      this.name = name;
53	      this.value = value;
54	    }
55	
56	    KeyVal() {
57	    }
58	
59	    @Override
60	    public String toString() {
61	      final StringBuilder sb = new StringBuilder("SimpleJson{");
62	      sb.append("name='").append(name).append('\'');
63	      sb.append(", value='").append(value).append('\'');
64	      sb.append('}');
65	      return sb.toString();
66	    }
67	
68	    @Override
69	    public boolean equals(Object o) {
70	      if (this == o) {
71	        return true;
72	      }
73	      if (o == null || getClass() != o.getClass()) {
74	        return false;
75	      }
76	      KeyVal that = (KeyVal) o;
77	      return Objects.equals(name, that.name) &&
78	          Objects.equals(value, that.value);
79	    }
80	
81	    @Override
82	    public int hashCode() {
83	      return Objects.hash(name, value);
84	    }
85	
86	    public String getName() {
87	      return name;
88	    }
89	
90	    public void setName(String name) {
91	      this.name = name;
92	    }
93	
94	    public String getValue() {
95	      return value;
96	    }
97	
98	    public void setValue(String value) {
99	      this.value = value;
100	    }
101	  }
102	
103	  @Test
104	  public void testStringRoundTrip() throws Throwable {
105	    String wire = serDeser.toJson(source);
106	    KeyVal unmarshalled = serDeser.fromJson(wire);
107	    assertEquals("Failed to unmarshall: " + wire, source, unmarshalled);
108	  }
